// ================= VOCABULARY v3: complete A1 word sets =================
// item: [emoji, finnish, english, nepali, example fi, example en, example ne]
function addWords(cat,meta,items){if(!NOUNS[cat])NOUNS[cat]={fi:meta[0],en:meta[1],ne:meta[2],items:[]};const have=new Set(NOUNS[cat].items.map(i=>i[1]));for(const it of items)if(!have.has(it[1])){NOUNS[cat].items.push(it);have.add(it[1])}}
